insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('021c5fa2-d17c-471e-9c48-a6543a75d3e2', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p>En la teoría newtoniana, en que el tiempo existía independientemente de todo lo demás, se podía preguntar: ¿qué hacía Dios antes de crear el universo? [...] Según San Agustín, antes de que Dios hiciera el cielo y la tierra no hacía nada en absoluto. De hecho, esta visión resulta muy próxima a las ideas actuales. En la relatividad general, el tiempo y el espacio no existen independientemente del universo o separadamente el uno del otro. Están definidos por medidas efectuadas dentro del universo, como el número de vibraciones de un cristal de cuarzo de un reloj o la longitud de una cinta métrica. Es fácilmente concebible que un tiempo definido de este modo, en el interior del universo, debe haber tenido un valor mínimo o un valor máximo —en otras palabras, un comienzo o un final—. No tendría sentido preguntar qué ocurrió antes del comienzo o después del fin, porque tales tiempos no estarían definidos.</p><p class="ctx-fuente"><small>Tomado y adaptado de: Hawking, S. (2002). El universo en una cáscara de nuez. Barcelona: Editorial Planeta.</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('cdc480e7-40e9-4ec6-9e3e-75e3f6a329f1', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<figure class="ctx-fig es-ancha" tabindex="0" aria-label="Imagen con desplazamiento horizontal"><img src="img/figuras/lc/s13-q64-comic.webp" style="min-width:900px" loading="lazy" alt="Página de cómic sobre cuánto mostrar y cuánto omitir. Una secuencia larga muestra a Carl prometiendo no conducir si bebe, yendo a ver a una amiga, recibiendo su negativa a salir, bebiendo, chocando y muriendo. Una versión más corta conserva la promesa, la bebida, el choque y la tumba. El narrador dice que en el cómic cuentan tanto la sustracción como la adición y que es crucial equilibrar lo demasiado con lo demasiado poco. Sus gafas tienen un cristal negro y uno blanco. El cierre muestra un ojo abierto y uno cerrado e indica que el lector los interpreta como un ojo que se cierra."><figcaption>Desliza la imagen hacia los lados para verla completa.</figcaption></figure><p>Considere la siguiente secuencia del cómic:</p><figure class="ctx-fig es-ancha" tabindex="0" aria-label="Imagen con desplazamiento horizontal"><img src="img/figuras/lc/s13-q64-secuencia.webp" style="min-width:420px" loading="lazy" alt="Seis viñetas: Carl saluda a Deisy; ella no puede salir con él esa noche; Carl pregunta qué hace ahora; bebe; se ve el choque de un carro y luego una tumba con su nombre."><figcaption>Desliza la imagen hacia los lados para verla completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('6b561dbc-602c-4680-89d9-5989a18a6a88', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<figure class="ctx-fig es-ancha" tabindex="0" aria-label="Imagen con desplazamiento horizontal"><img src="img/figuras/lc/s13-q64-comic.webp" style="min-width:900px" loading="lazy" alt="Página de cómic sobre cuánto mostrar y cuánto omitir. Una secuencia larga muestra a Carl prometiendo no conducir si bebe, yendo a ver a una amiga, recibiendo su negativa a salir, bebiendo, chocando y muriendo. Una versión más corta conserva la promesa, la bebida, el choque y la tumba. El narrador dice que en el cómic cuentan tanto la sustracción como la adición y que es crucial equilibrar lo demasiado con lo demasiado poco. Sus gafas tienen un cristal negro y uno blanco. El cierre muestra un ojo abierto y uno cerrado e indica que el lector los interpreta como un ojo que se cierra."><figcaption>Desliza la imagen hacia los lados para verla completa.</figcaption></figure><p>Considere la siguiente viñeta:</p><figure class="ctx-fig es-ancha" tabindex="0" aria-label="Imagen con desplazamiento horizontal"><img src="img/figuras/lc/s13-q65-lentes.webp" style="min-width:420px" loading="lazy" alt="El narrador, con gafas cuyos lentes llevan formas negras y blancas, dice: «Y dar con el equilibrio entre lo DEMASIADO y lo DEMASIADO POCO es crucial para todo creador del mundo del cómic». Antes del recorte se ve el mismo globo completo."><figcaption>Desliza la imagen hacia los lados para verla completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('dcc7beda-1f20-4586-a44f-76db5258f2c2', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p>Cuando llega la hora de poner sus huevos, la avispa Sphex construye una pequeña madriguera para este propósito y sale en la búsqueda de un grillo al cual pica de manera tal que lo paraliza, pero no lo mata. La avispa lleva al grillo a su madriguera, deja sus huevos, cierra la madriguera y luego se va para no volver. Pasado un tiempo, los huevos crecen y la cría de la avispa se alimenta del grillo paralizado que no se descompone debido a que ha permanecido congelado. Para la mente humana, tal rutina tan organizada y aparentemente llena de propósitos lleva consigo un sabor de lógica y de pensamiento. O por lo menos esto es así hasta que conocemos más detalles.</p><p>Por ejemplo, la rutina de la avispa consiste en llevar al grillo hacia la madriguera, dejarlo en la entrada, ir adentro a revisar que todo esté bien, salir y luego dejar el grillo adentro. Si, mientras la avispa está dentro de la madriguera haciendo su inspección preliminar, el grillo es movido algunos centímetros de la entrada, la avispa, al salir de la madriguera, volverá a dejar al grillo de nuevo en la entrada, pero no adentro, y repetirá el procedimiento preparatorio de entrar a la madriguera a revisar que todo esté bien. Si, de nuevo, el grillo es movido unos centímetros de la entrada, la avispa llevará otra vez al grillo hacia la entrada y volverá a entrar a la madriguera para revisarla. La avispa nunca piensa en llevar al grillo directamente a su madriguera. En una ocasión, este procedimiento fue repetido cuarenta veces, siempre con el mismo resultado.</p><p class="ctx-fuente"><small>Tomado y adaptado de: Woolridge, Dean E. (1963). The Machinery of the Brain. New York: McGraw-Hill, pp. 82–83.</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('a72ab58d-5cb1-4a2d-837a-930056cff4eb', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p>Cuando llega la hora de poner sus huevos, la avispa Sphex construye una pequeña madriguera para este propósito y sale en la búsqueda de un grillo al cual pica de manera tal que lo paraliza, pero no lo mata. La avispa lleva al grillo a su madriguera, deja sus huevos, cierra la madriguera y luego se va para no volver. Pasado un tiempo, los huevos crecen y la cría de la avispa se alimenta del grillo paralizado que no se descompone debido a que ha permanecido congelado. Para la mente humana, tal rutina tan organizada y aparentemente llena de propósitos lleva consigo un sabor de lógica y de pensamiento. O por lo menos esto es así hasta que conocemos más detalles.</p><p>Por ejemplo, la rutina de la avispa consiste en llevar al grillo hacia la madriguera, dejarlo en la entrada, ir adentro a revisar que todo esté bien, salir y luego dejar el grillo adentro. Si, mientras la avispa está dentro de la madriguera haciendo su inspección preliminar, el grillo es movido algunos centímetros de la entrada, la avispa, al salir de la madriguera, volverá a dejar al grillo de nuevo en la entrada, pero no adentro, y repetirá el procedimiento preparatorio de entrar a la madriguera a revisar que todo esté bien. Si, de nuevo, el grillo es movido unos centímetros de la entrada, la avispa llevará otra vez al grillo hacia la entrada y volverá a entrar a la madriguera para revisarla. La avispa nunca piensa en llevar al grillo directamente a su madriguera. En una ocasión, este procedimiento fue repetido cuarenta veces, siempre con el mismo resultado.</p><p class="ctx-fuente"><small>Tomado y adaptado de: Woolridge, Dean E. (1963). The Machinery of the Brain. New York: McGraw-Hill, pp. 82–83.</small></p><p><b>Considere el siguiente párrafo.</b></p><p>Los comportamientos instintivos pueden ser irracionales, especialmente cuando operan en condiciones distintas a aquellas en las que presumiblemente se desarrollaron. Sin embargo, ni el comportamiento instintivo ni la posibilidad de reducir nuestro comportamiento complejo a elementos racionales más básicos son muestras de que no podemos actuar racionalmente, del mismo modo que casos locales de irracionalidad en la avispa Sphex no nos enseñan nada sobre la racionalidad de la avispa cuando se comporta en condiciones normales.</p><p class="ctx-fuente"><small>Tomado y adaptado de Vargas, Manuel (2013). Decomposing the will. Ed. Till Vierkant, Julian Kivertein and Andy Clark. New York: Oxford University Press.</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('7f8c8f9d-edc3-4207-ac40-3bb609331cfe', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<figure class="ctx-fig es-ancha" tabindex="0" aria-label="Imagen con desplazamiento horizontal"><img src="img/figuras/lc/s13-q69-dinos.webp" style="min-width:640px" loading="lazy" alt="Historieta de cuatro viñetas. Calvin anuncia que escribirá sobre si los tiranosaurios eran temibles depredadores o desagradables carroñeros. Hobbes pregunta qué posición defenderá. Calvin responde que cree que eran temibles depredadores. Cuando Hobbes le pregunta por qué, contesta: «¡Son mucho más geniales de esa manera!»."><figcaption>Desliza la imagen hacia los lados para verla completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('55c50a2e-e2c3-4ef3-a48c-36a3e78456c3', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<figure class="ctx-fig es-ancha" tabindex="0" aria-label="Imagen con desplazamiento horizontal"><img src="img/figuras/lc/s13-q72-fuego.webp" style="min-width:640px" loading="lazy" alt="Historieta de ocho cuadros. Un hombre prehistórico frota palos, obtiene una llama y la observa con asombro. Al tocarla grita. Una mujer pregunta qué es; él responde que no sabe. Ella dice que sí sabe y arroja lo producido a un barranco donde hay varios inventos descartados, mientras dice: «Otra de esas estupideces que te pasas inventando»."><figcaption>Desliza la imagen hacia los lados para verla completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('4cf018c3-d106-4df6-a7ef-412983c439f7', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p><b>Por qué revistas como Nature, Science y Cell hacen daño a la ciencia</b></p><p>El mío es un mundo profesional en el que se logran grandes cosas para la humanidad. Pero está desfigurado por unos incentivos inadecuados. Los sistemas imperantes de la reputación personal y el ascenso profesional significan que las mayores recompensas a menudo son para los trabajos más llamativos, no para los mejores. Aquellos de nosotros que respondemos a estos incentivos estamos actuando de un modo perfectamente lógico —yo mismo he actuado movido por ellos, pero no siempre poniendo los intereses de nuestra profesión por encima de todo, por no hablar de los de la humanidad y la sociedad.</p><p>Todos sabemos lo que los incentivos distorsionadores han hecho a las finanzas y la banca. Los incentivos que se ofrecen a mis compañeros no son unas primas descomunales, sino las recompensas profesionales que conllevan el hecho de publicar en revistas de prestigio, principalmente Nature, Cell y Science. Se supone que estas publicaciones de lujo son el paradigma de la calidad, que publican solo los mejores trabajos de investigación. Dado que los comités encargados de la financiación y los nombramientos suelen usar el lugar de publicación como indicador de la calidad de la labor científica, el aparecer en estas publicaciones suele traer consigo subvenciones y cátedras. Pero la reputación de las grandes revistas solo está garantizada hasta cierto punto. Aunque publican artículos extraordinarios, eso no es lo único que publican. Ni tampoco son las únicas que publican investigaciones sobresalientes.</p><p>Estas revistas promocionan de forma agresiva sus marcas, de una manera que conduce más a la venta de suscripciones que a fomentar las investigaciones más importantes. Al igual que los diseñadores de moda que crean bolsos o trajes de edición limitada, saben que la escasez hace que aumente la demanda, de modo que restringen artificialmente el número de artículos que aceptan. Luego, estas marcas exclusivas se comercializan empleando un ardid llamado «factor de impacto»: una puntuación otorgada a cada revista que mide el número de veces que los trabajos de investigación posteriores citan sus artículos.</p><p>Pero como la puntuación de la publicación es una media, dice poco de la calidad de cualquier investigación concreta. Además, las citas están relacionadas con la calidad a veces, pero no siempre. Un artículo puede ser muy citado porque es un buen trabajo científico, o bien porque es llamativo, provocador o erróneo. Los directores de las revistas de lujo lo saben, así que aceptan artículos que tendrán mucha repercusión porque estudian temas atractivos o hacen afirmaciones que cuestionan ideas establecidas. Esto influye en los trabajos que realizan los científicos. Crea burbujas en temas de moda en los que los investigadores pueden hacer las afirmaciones atrevidas que estas revistas buscan, pero no anima a llevar a cabo otras investigaciones importantes.</p><p>Al igual que Wall Street tiene que acabar con el dominio de la cultura de las primas, que fomenta unos riesgos que son racionales para los individuos, pero perjudiciales para el sistema financiero, la ciencia debe liberarse de la tiranía de las revistas de lujo. La consecuencia será una investigación mejor que sirva mejor a la ciencia y a la sociedad.</p><p class="ctx-fuente"><small>Adaptado de: Shekman, Randy, «Por qué revistas como Nature, Science y Cell hacen daño a la ciencia», en El País, 12 de diciembre de 2013.</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('d02cd4ac-f22c-4f21-82e4-1c7c4c85390e', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p>Por si no viven en Nueva York, les diré que el Wicker Bar está en un hotel muy elegante, el Seton. Antes me gustaba mucho, pero poco a poco fui dejando de ir. Es uno de esos sitios que se consideran muy finos y donde se ven farsantes a patadas. Había dos chicas francesas, Tina y Janine, que actuaban tres veces por noche. Una de ellas tocaba el piano, —lo asesinaba—, y la otra cantaba siempre unas canciones o muy verdes o en francés. La tal Janine se ponía delante del micrófono, y antes de empezar la actuación decía como susurrando: «Y ahoja les pejsentamos nuestja vejsión de Vulé vú fjansé. Es la histoja de una fjansesita que llega a una gjan siudad como Nueva Yojk y se enamojá de un muchachito de Bjooklyn. Espejo que les guste». Cuando acababa de susurrar y de demostrar lo graciosa que era, cantaba medio en francés medio en inglés una canción tontísima que volvía locos a todos los imbéciles del bar. Si te pasabas allí un buen rato oyendo aplaudir a ese hatajo de idiotas, acababas odiando a todo el mundo. De verdad.</p><p class="ctx-fuente"><small>Tomado de: Salinger, J. D. (2002). El guardián entre el centeno. Madrid: Alianza Editorial.</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('c6bd98d2-b599-4b6e-b462-0bb938059243', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p>A las diez de la noche, finalmente, apareció el primer ministro. Venía con el rostro demudado, con ojeras profundas, efectos de una semana entera de noches mal dormidas, pálido a pesar del maquillaje tipo buena salud. Traía un papel en la mano, pero casi no lo leyó, apenas le lanzó una que otra mirada para no perder el hilo del discurso, queridos conciudadanos, dijo, el resultado de las elecciones que hoy se han realizado en la capital es el siguiente, partido de la derecha, ocho por ciento, partido del medio, ocho por ciento, partido de la izquierda, uno por ciento, abstenciones, cero, votos nulos, cero, votos en blanco, ochenta y tres por ciento. Hizo una pausa para acercarse a los labios el vaso de agua que tenía al lado y prosiguió, el gobierno, reconociendo que la votación de hoy confirma, agravándola, la tendencia verificada el pasado domingo y estando unánimemente de acuerdo sobre la necesidad de una seria investigación de las causas primeras y últimas de tan desconcertantes resultados, considera, tras deliberar con su excelencia el jefe de estado, que su legitimidad para seguir en funciones no ha sido puesta en causa, ya que la convocatoria ahora concluida era solo local, y que además reivindica y asume como su imperiosa y urgente obligación investigar hasta las últimas consecuencias los anómalos acontecimientos de que fuimos, durante la última semana, aparte de atónitos testigos, temerarios actores, y si, con el más profundo pesar, pronuncio esta palabra, es porque los votos en blanco, que han asestado un golpe brutal a la normalidad democrática en que transcurría nuestra vida personal y colectiva, no cayeron de las nubes ni subieron de las entrañas de la tierra, estuvieron en el bolsillo de ochenta y tres de cada cien electores de esta ciudad, los cuales, con su propia, pero no patriótica mano, los depositaron en las urnas. Otro trago de agua, este más necesario porque la boca se le ha secado de repente, todavía estamos a tiempo de enmendar el error, no a través de nuevas elecciones, que en el estado actual podrían ser, aparte de inútiles, contraproducentes, sino a través del riguroso examen de conciencia al que desde esta tribuna pública, convoco a los habitantes de la capital, a todos ellos, a unos para que puedan protegerse mejor de la terrible amenaza que flota sobre sus cabezas, a otros, sean culpables, sean inocentes de intención, para que se corrijan de la maldad a que se dejaron arrastrar a saber por quién, bajo pena de convertirse en blanco directo de las sanciones previstas en el ámbito de estado de excepción cuya declaración, tras consulta, mañana mismo, al parlamento, que para el efecto se reunirá en sesión extraordinaria, y obtenida, como se espera, su aprobación unánime, el gobierno va a solicitar a su excelencia el jefe de estado.</p><p class="ctx-fuente"><small>Tomado de: Saramago, J. (2004). Ensayo sobre la lucidez. México: Alfaguara.</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('42c68b30-1c9b-41a1-9e85-17bd092b58fc', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p>SÓCRATES (...): Y por mi parte, si el torpedo, estando él mismo entorpecido, es como hace que los demás se entorpezcan, me parezco a él; pero si no, no. Porque no es teniendo yo claridad como induzco a confusión a los otros, sino que es estando yo en mayor confusión que nadie como hago que lo estén los otros. Y así, ahora, acerca de la virtud, qué es, yo desde luego no lo sé; tú, sin embargo, quizá sí lo sabías antes de ponerte en contacto conmigo, y ahora, en cambio, parece como si no lo supieras. Aun así estoy decidido a considerar e investigar contigo qué es.</p><p>MENÓN: ¿Y de qué manera vas a investigar, Sócrates, lo que no sabes en absoluto qué es? Porque, ¿qué es lo que, de entre cosas que no sabes, vas a proponer como tema de investigación? O, aun en el caso favorable de que lo descubras, ¿cómo vas a saber que es precisamente lo que tú no sabías?</p><p>SÓCRATES: Ya entiendo lo que quieres decir, Menón. ¿Te das cuenta del argumento polémico que nos traes, a saber, que no es posible para el hombre investigar ni lo que sabe ni lo que no sabe? Pues ni sería capaz de investigar lo que sabe, puesto que lo sabe, y ninguna necesidad tiene un hombre así de investigación, ni lo que no sabe, puesto que ni siquiera sabe qué es lo que va a investigar.</p><p class="ctx-fuente"><small>Tomado de: Menón, 79a-b. Ed. Gredos. Madrid.</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('9f600efd-eb88-4146-a5d9-d1200b1e4799', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<figure class="ctx-fig es-ancha" tabindex="0" aria-label="Imagen con desplazamiento horizontal"><img src="img/figuras/lc/s13-q86-corrupcion.webp" style="min-width:640px" loading="lazy" alt="Infografía titulada «Las medidas de Rajoy contra la corrupción». El gobierno propone un pacto con todas las fuerzas políticas. Enumera seis medidas: extender la ley de transparencia a partidos y sindicatos financiados con fondos públicos; endurecer las penas; registro público de las cuentas de los partidos; doble control a sus responsables económicos; declaraciones tributarias y de bienes de cargos públicos; y fiscalizar ingresos y gastos de fundaciones vinculadas a los partidos. Los símbolos incluyen una lupa sobre dinero, una celda, billetes, una persona que observa una bolsa, globos con el signo del euro y edificios."><figcaption>Desliza la imagen hacia los lados para verla completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('e1a296d6-a34c-437b-b012-8feac6fb91ed', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p><b>Consejos para la juventud</b></p><p>Cuando me informaron sobre mi participación aquí, pregunté sobre el tema que pretendían que abordase. Me dijeron que debía de ser algo apropiado para la juventud —algo didáctico, instructivo, o algo en los órdenes del buen consejo—. Muy bien. Tengo algunas cosas en mente que desde hace tiempo quiero decir para instrucción de los jóvenes, pues a tan tierna edad es cuando cosas por el estilo arraigan mejor y son más duraderas y valiosas: Primero, entonces, les diré a ustedes, mis jóvenes amigos, —y lo diré en tono urgente y suplicante—: obedezcan siempre a sus padres. Esta es la mejor política a la larga, porque si uno no lo hace ellos lo obligan. Los padres en su mayoría creen tener mejor criterio que uno, y uno por lo general se la pasa mejor honrando semejante superstición que actuando según su mejor criterio.</p><p>Ahora, sobre el asunto de mentir. Debes ser muy cuidadoso en esta materia; de otra manera es casi seguro que serás atrapado. Una vez atrapado, no puedes volver a ser, a los ojos de los buenos y de los puros, lo que eras antes. Muchos jóvenes se han lastimado a sí mismos de forma permanente a causa de alguna mentira torpe y mal ejecutada, siendo el descuido consecuencia de un entrenamiento incompleto. Algunas autoridades afirman que los jóvenes no deberían de mentir para nada.</p><p>Esta opinión, desde luego, es algo exagerada; con todo, aunque no es dado llegar a tal extremo, mantengo, y creo tener en ello la razón, que los jóvenes han de moderarse en el uso de este gran arte hasta que la práctica y la experiencia les hayan dado la confianza, la elegancia y la precisión sin las cuales no se consiguen resultados pulcros y ventajosos. Paciencia, diligencia, atención al más mínimo detalle —he ahí los requerimientos, sobre estos, y solamente sobre estos, se ha de cimentar toda futura eminencia—.</p><p>Piense en los años de estudio tedioso, pensamiento, práctica y experiencia hubo de requerir el entrenamiento de aquel incomparable maestro de la Antigüedad que fue capaz de imponer al mundo entero la pulida y sonora máxima de que «la verdad es poderosa y prevalece» —la más majestuosa impostura de los hechos comprobables que hasta el día de hoy un nacido de mujer haya logrado acreditar—. Pues la historia de nuestra raza, para no hablar de las experiencias individuales, está densamente tejida con la evidencia de que una verdad no es difícil de extirpar en tanto que una mentira bien contada es inmortal.</p><p class="ctx-fuente"><small>Tomado de: Twain, Mark (1882). Consejos para la juventud. Recuperado de salaciencia.blogspot.com/2012/01/consejos-para-la-juventud-1882-de-mark.html</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('8223e962-069d-4091-8a37-5e25afecbb43', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p><b>Mauki</b></p><p>Pesa ciento diez libras. Tenía el pelo ensortijado y su piel era negra. Pero de un negro muy especial: ni azulado ni rojizo, sino tirando a ciruela. Se llamaba Mauki y era hijo de un jefe. Tenía tres tambos, palabra melanesia que significa «prohibición» y es prima hermana del término polinesio tabú. Los tres tambos de Mauki eran los siguientes: primero, no podía estrechar manos femeninas ni podía permitir que mujer alguna le tocara ni a él ni a ninguna de sus pertenencias. Segundo, no podía comer almejas ni alimento alguno guisado sobre un fuego al calor del cual se hubieran cocinado dichos moluscos. Tercero, no podía cazar cocodrilos ni navegar en canoas que transportan una parte de este animal por pequeña que fuera, aunque solo se tratara de un diente.</p><p>Tenía la dentadura de un negro distinto, intenso o, mejor dicho, de un negro hollín. Se la había teñido su madre en una sola noche frotándola con un mineral en polvo procedente de un yacimiento que había a espaldas de Port Adams, poblado marinero de Malaita, la más indómita de las islas del archipiélago de las Salomón, tan indómita que ni los comerciantes ni colonos han logrado hasta ahora poner el pie en ella. Desde los tiempos de los primeros pescadores de cohombro de mar y comerciantes de sándalo, hasta los días recientes de negros provistos de rifles automáticos y motores de gasolina, decenas y decenas de aventureros blancos han muerto en esa isla víctimas de las hachas y las balas explosivas de los nativos [...]</p><p>Mauki tenía las orejas agujereadas, no en un sitio ni en dos, sino en un par de docenas. En uno de los orificios más pequeños llevaba una pipa de cerámica. Los mayores eran demasiado grandes para tal adorno. La cazuela de la pipa habría pasado a través de ellos. De hecho, en el agujero más grande de cada oreja llevaba tapones redondos de madera de unas cuatro pulgadas de diámetro. La circunferencia de dichas aberturas medía aproximadamente doce pulgadas y media. Mauki no era muy especial en sus gustos.</p><p>En los orificios más pequeños llevaba entre otras cosas casquillos vacíos, clavos, tornillos de cobre, pedazos de cuerda, briznas de cables trenzados, tiritas de hojas verdes y, al atardecer, con la fresca, flores de color escarlata. De ello se deducirá que para andar por la vida no necesitaba bolsillos, los cuales, por otra parte, le estaban vedados por consistir toda su indumentaria en un trozo de percal de varias pulgadas de anchura. En la cabeza lucía una navaja con la hoja cerrada sobre un rizo de cabello.</p><p>Su posesión más preciada era el asa de un tazón de porcelana que llevaba colgada de un anillo de concha de tortuga pendiente a su vez del tabique nasal. Pero a pesar de estos adornos, su cara resultaba agradable. Era el suyo un rostro hermoso desde cualquier punto de vista, sobre todo tratándose de un nativo de la Melanesia. Sólo tenía un defecto: le faltaba firmeza.</p><p class="ctx-fuente"><small>Tomado de: London, J. (1986). Relatos de mares del sur, pp. 40–41. Madrid: Alianza.</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('dfe1325d-2936-42f7-b3b1-29cce190c3a2', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<p>Johny conocía a un tipo. A secas. Johny era así, uno le decía: me encantaría multiplicar mis ahorros por mil. Y él: conozco a un tipo. Me encantaría viajar a Cuba, comprar unos habanos y volver. ¿Para qué? Para venderlos. Conozco a un tipo.</p><p>Me encantaría hacerme un tatuaje. ¿Dónde? En la nuca. Conozco a un tipo.</p><p>Me encantaría quedarme acá siempre. Y ahí Johny ya no conocía a nadie. Decía: este es un país muy duro. Pero él vivía como un magnate, cambiaba de carro cada seis meses y seguía pagando el mismo leasing; cobraba subsidio de desempleo que nadie le controlaba y era con eso que pagaba los moteles donde tirábamos, o las langostas que nos comíamos en Key West, o los VIP passes de los bares de salsa a los que le gustaba llevarme en Calle Ocho.</p><p>Johny vivía a expensas de su mujer —mitad gringa, mitad ecuatoriana— y compraba hasta los calzoncillos de marca: alimentaba rigurosamente su pequeño sueño americano como si temiera que, si un día se olvidaba de hacerlo, se desplomara a sus pies como un pajarito famélico.</p><p class="ctx-fuente"><small>Tomado de: García Robayo, M. (2015). Hasta que pase un huracán. Bogotá D. C.: Laguna Libros.</small></p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('b66492f7-169c-4773-9766-7d7347c705f6', 'pasaje', 'LECTURA CRÍTICA', 'ctx-pasaje', '<figure class="ctx-fig es-ancha" tabindex="0" aria-label="Imagen con desplazamiento horizontal"><img src="img/figuras/lc/s13-q95-loros.webp" style="min-width:900px" loading="lazy" alt="Infografía «Un mar de loros». Describe una colonia de loros barranqueros en El Cóndor, Río Negro. Informa más de 175 mil ejemplares en verano y unos 35 mil nidos en acantilados. Los nidos miden cerca de 1,5 metros de profundidad, pueden interconectarse y cada uno aloja una pareja. Las parejas reutilizan y agrandan sus nidos. Una tabla muestra ocupación de nidos en septiembre, incubación en octubre, nacimiento en noviembre, cría en diciembre y vuelo en enero. Se ilustran aves, nidos y las etapas de cría. Describe alimentación, migración, amenazas por persecución y captura ilegal y medidas de protección."><figcaption>Desliza la imagen hacia los lados para verla completa.</figcaption></figure>');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '7b015ece-2ee3-4b40-86cd-f5aae5a3ee3e', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'funcion-de-expresiones'),
  (select id from public.lotes where codigo = '2026-B'),
  '021c5fa2-d17c-471e-9c48-a6543a75d3e2', 'Función de expresiones',
  'La referencia a San Agustín en el texto cumple la función de',
  array['recurrir a una autoridad para defender una tesis sobre Dios.', 'sugerir que la ciencia y la religión no son completamente incompatibles.', 'mostrar el papel que desempeña Dios en las discusiones cosmológicas actuales.', 'introducir la concepción actual del tiempo a partir de una afirmación sobre Dios.'],
  'Observa qué idea desarrolla el autor inmediatamente después de mencionar a San Agustín.', 'publicada', 'modelo', '7b95146834b19b9d8ff56cb2c413f53a', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('7b015ece-2ee3-4b40-86cd-f5aae5a3ee3e', 3, 'El autor pasa de la pregunta sobre Dios a la relación entre el tiempo y el universo. San Agustín sirve como punto de entrada a esa explicación; el pasaje no busca demostrar una tesis religiosa.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'd27ed9fa-7172-4e03-95d1-05038363550a', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  '021c5fa2-d17c-471e-9c48-a6543a75d3e2', 'Inferencia',
  'La última frase del texto presenta una idea compatible con la de San Agustín, porque de esta frase se sigue que',
  array['la indefinición del tiempo deja abierta la posibilidad de la existencia de Dios.', 'Dios no podría estar haciendo algo antes del origen del universo, ya que no existió tal período.', 'el comienzo del universo es anterior a la creación del cielo y de la tierra.', 'para la ciencia actual solo es relevante lo que Dios hubiera podido haber hecho dentro del universo.'],
  'Relaciona «antes del comienzo» con «tales tiempos no estarían definidos».', 'publicada', 'modelo', 'b8105bc07c37266c3ccc275ec9dd6583', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('d27ed9fa-7172-4e03-95d1-05038363550a', 1, 'Según el pasaje, un antes del comienzo del universo no sería un tiempo definido. Por eso la pregunta sobre qué hacía Dios en ese período pierde su supuesto temporal.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'c36e6566-a1bc-48b2-a5b1-f35c97969f67', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'tesis-y-argumentos'),
  (select id from public.lotes where codigo = '2026-B'),
  '021c5fa2-d17c-471e-9c48-a6543a75d3e2', 'Tesis y argumentos',
  '¿Cuál de las siguientes afirmaciones es la antítesis de la tesis principal del texto?',
  array['El tiempo existe independientemente de que exista el universo.', 'Las ideas de San Agustín están desactualizadas.', 'El universo no tiene principio ni fin.', 'Dios es el creador del universo.'],
  'Busca la negación de la relación entre tiempo y universo.', 'publicada', 'modelo', '5a99d212c8ed1b7a13e2f0d16a7be06f', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c36e6566-a1bc-48b2-a5b1-f35c97969f67', 0, 'El texto sostiene que el tiempo se define dentro del universo. Afirmar que existe independientemente de él contradice directamente esa relación.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '2a86fa45-72a6-4412-9d53-7e3a85474b00', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'textos-discontinuos'),
  (select id from public.lotes where codigo = '2026-B'),
  'cdc480e7-40e9-4ec6-9e3e-75e3f6a329f1', 'Textos discontinuos',
  'Teniendo en cuenta el resto del cómic, ¿cuál de las siguientes opciones describe mejor la secuencia anterior?',
  array['Al no poder salir con una amiga, Carl decide tomarse unos tragos y, bajo efectos del alcohol, maneja, se estrella y muere.', 'Al ser rechazado por una mujer, Carl no sabe qué hacer con su vida y toma la decisión de suicidarse estrellando el carro contra un árbol.', 'Al no poder salir con una amiga, Carl se estrella y muere debido a que se distrae con una bebida, mientras conduce camino a casa.', 'Al ser rechazado por una mujer, Carl resuelve manejar a toda velocidad y termina por estrellar su carro contra un árbol.'],
  'Usa también la promesa que aparece al comienzo de la historia.', 'publicada', 'modelo', '1bcbbbaa76f9d4f035336b61b8f3dfd0', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('2a86fa45-72a6-4412-9d53-7e3a85474b00', 0, 'La promesa inicial de no conducir si bebe permite relacionar la bebida con el choque posterior. No se muestra una intención de suicidio, una distracción al beber mientras conduce ni una decisión de acelerar.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '2103310b-78b4-4f49-a0dc-ee4180133ffd', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'textos-discontinuos'),
  (select id from public.lotes where codigo = '2026-B'),
  '6b561dbc-602c-4680-89d9-5989a18a6a88', 'Textos discontinuos',
  'En este recuadro los lentes del personaje representan:',
  array['la armonía narrativa que un autor, a fin de evitar carencias o excesos de contenido, debe plasmar en su cómic.', 'la visión doble que deben tener los autores de los cómics para poder ver sus creaciones desde su punto de vista y desde el punto de vista del lector.', 'la gran capacidad imaginativa y creadora que, como se explica en el texto, es un elemento crucial para todo creador del mundo del cómic.', 'la simetría contextual que debe existir entre los elementos gráficos y textuales que conforman el relato de un cómic.'],
  'Lee el globo del mismo recuadro antes de interpretar los lentes.', 'publicada', 'modelo', 'c4fd5a55dba8174a25e4b438056d0228', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('2103310b-78b4-4f49-a0dc-ee4180133ffd', 0, 'El contraste entre los dos lentes acompaña la frase sobre equilibrar los extremos de exceso y falta de información. Esa relación concreta sostiene la interpretación de una armonía narrativa.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'c38c5ebf-a1d6-4987-99cb-71479131eae3', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'tesis-y-argumentos'),
  (select id from public.lotes where codigo = '2026-B'),
  'dcc7beda-1f20-4586-a44f-76db5258f2c2', 'Tesis y argumentos',
  '¿Cuál de las siguientes citas refuerza la idea de que el comportamiento de la avispa Sphex no resulta de un proceso de pensamiento racional?',
  array['«La avispa lleva al grillo a su madriguera, deja sus huevos, cierra la madriguera y luego se va para no volver».', '«La avispa nunca piensa en llevar al grillo directamente a su madriguera. En una ocasión, este procedimiento fue repetido cuarenta veces, siempre con el mismo resultado».', '«Para la mente humana, tal rutina tan organizada y aparentemente llena de propósitos lleva consigo un sabor de lógica y de pensamiento».', '«Por ejemplo, la rutina de la avispa consiste en llevar al grillo hacia la madriguera, dejarlo en la entrada, ir adentro a revisar que todo esté bien, salir y luego dejar el grillo adentro».'],
  'Busca el resultado de alterar repetidamente la situación.', 'publicada', 'modelo', '8d6e06dc41b7df8d0bb6c734f3ecc05f', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c38c5ebf-a1d6-4987-99cb-71479131eae3', 1, 'Repetir el procedimiento sin ajustarlo a la alteración es la evidencia que el autor usa para cuestionar la apariencia de deliberación. Describir solo la rutina no demuestra esa falta de flexibilidad.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'ad355070-fff5-4f01-b680-f8bf58fa95cc', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'proposito-del-texto'),
  (select id from public.lotes where codigo = '2026-B'),
  'dcc7beda-1f20-4586-a44f-76db5258f2c2', 'Propósito del texto',
  '¿Cuál de los siguientes enunciados sintetiza el tema principal del texto?',
  array['El comportamiento aparentemente inteligente de la avispa Sphex.', 'El papel de los grillos en la alimentación de las avispas Sphex.', 'La avispa Sphex como un caso que prueba la inteligencia animal.', 'Los métodos de crianza y las precauciones de las avispas Sphex.'],
  'Incluye en la síntesis tanto la apariencia inicial como la prueba posterior.', 'publicada', 'modelo', 'a68eb083596fa3717a151e3a905a4879', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('ad355070-fff5-4f01-b680-f8bf58fa95cc', 0, 'El pasaje presenta una conducta que parece deliberada y luego muestra por qué esa apariencia puede engañar. Alimentación y crianza son partes del ejemplo, no el tema que lo organiza.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'cbec9ad9-7a8d-4a0b-926f-d0d0d034f75b', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'evaluacion-critica'),
  (select id from public.lotes where codigo = '2026-B'),
  'a72ab58d-5cb1-4a2d-837a-930056cff4eb', 'Evaluación crítica',
  'Este párrafo',
  array['apoya el texto de Woolridge.', 'cuestiona el texto de Woolridge.', 'explica el texto de Woolridge.', 'sintetiza el texto de Woolridge.'],
  'Compara lo que permite concluir cada autor a partir del caso.', 'publicada', 'modelo', '61657ba8f63d799d0da7bf808ae97755', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('cbec9ad9-7a8d-4a0b-926f-d0d0d034f75b', 1, 'Vargas objeta que un fallo en condiciones alteradas permita concluir algo general sobre la racionalidad en condiciones normales. Por eso cuestiona el alcance de la interpretación del experimento.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'e49d2e9c-bda8-453d-9376-97f19eb2ae93', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'informacion-literal'),
  (select id from public.lotes where codigo = '2026-B'),
  '7f8c8f9d-edc3-4207-ac40-3bb609331cfe', 'Información literal',
  'El niño afirma que los tiranosaurios son depredadores porque',
  array['así son más temibles.', 'así son más geniales.', 'no son carroñeros.', 'cazan presas.'],
  'Lee la respuesta a «¿Por qué lo dices?».', 'publicada', 'modelo', '97da39fc838145eb61ae2dd12a3effd4', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('e49d2e9c-bda8-453d-9376-97f19eb2ae93', 1, 'La última viñeta expresa su razón: le parecen más geniales como depredadores. No ofrece datos sobre su alimentación.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'e065e4b4-26ac-43c3-a78e-d5c3369ddfc4', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'proposito-del-texto'),
  (select id from public.lotes where codigo = '2026-B'),
  '7f8c8f9d-edc3-4207-ac40-3bb609331cfe', 'Propósito del texto',
  '¿Cuál es el tema del trabajo del niño?',
  array['¿Por qué los tiranosaurios son geniales?', '¿Por qué los tiranosaurios son depredadores?', '¿Son los tiranosaurios temibles o desagradables?', '¿Son los tiranosaurios depredadores o carroñeros?'],
  'Distingue el debate anunciado de la postura que el niño elige.', 'publicada', 'modelo', '259a66245094d9b7d6d3f1d833856b05', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('e065e4b4-26ac-43c3-a78e-d5c3369ddfc4', 3, 'En la segunda viñeta anuncia el debate que va a tratar: si eran depredadores o carroñeros. Su preferencia personal aparece después.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '50076114-1873-4113-9763-235cf3d45194', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  '7f8c8f9d-edc3-4207-ac40-3bb609331cfe', 'Inferencia',
  'Según lo dicho por el niño, se puede suponer que los tiranosaurios',
  array['son geniales, aún si no resultan ser depredadores.', 'no son geniales, si resulta que no son depredadores.', 'son geniales, solamente si resultan ser depredadores.', 'son depredadores, solamente si resultan ser geniales.'],
  'Distingue una comparación de grado de una condición necesaria.', 'borrador', 'modelo', '75ce9fb24eaebea9db2a2ec40ff2d814', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('50076114-1873-4113-9763-235cf3d45194', 2, 'Pregunta en borrador. Las opciones «no son geniales si no son depredadores» y «son geniales solamente si son depredadores» expresan la misma condición necesaria. Además, decir «más geniales» no implica que dejen de ser geniales en el otro caso. No se debe calificar con una clave única.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '42f28919-db0a-42a4-8864-028b5cf051a9', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'textos-discontinuos'),
  (select id from public.lotes where codigo = '2026-B'),
  '55c50a2e-e2c3-4ef3-a48c-36a3e78456c3', 'Textos discontinuos',
  'Observe el cuadro 8. En relación con los objetos que se muestran en el piso, la frase de la mujer',
  array['es una descripción fiel de esos objetos.', 'hace referencia a solo uno de esos objetos.', 'refleja su opinión sobre esos objetos.', 'no se refiere a esos objetos.'],
  'Separa la valoración del personaje de lo que los objetos son.', 'publicada', 'modelo', '7be493cf708b1844c5c86396a38d21c8', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('42f28919-db0a-42a4-8864-028b5cf051a9', 2, '«Estupideces» comunica una valoración despectiva de los inventos. No es una descripción neutral de sus propiedades.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'f7e95ee3-3b78-4257-a972-528356ba4c28', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'textos-discontinuos'),
  (select id from public.lotes where codigo = '2026-B'),
  '55c50a2e-e2c3-4ef3-a48c-36a3e78456c3', 'Textos discontinuos',
  'Los cuadros 2 y 3 son similares porque en ambos el personaje expresa',
  array['indiferencia.', 'miedo.', 'sorpresa.', 'preocupación.'],
  'Observa la expresión y los signos de los dos cuadros indicados.', 'publicada', 'modelo', 'd373db224312a764379e58aaaa892045', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f7e95ee3-3b78-4257-a972-528356ba4c28', 2, 'La interrogación y su atención a la llama muestran desconcierto ante algo recién descubierto. El dolor ocurre después, cuando la toca.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '99924e71-fdb1-4570-b943-0046d1f8c379', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'proposito-del-texto'),
  (select id from public.lotes where codigo = '2026-B'),
  '4cf018c3-d106-4df6-a7ef-412983c439f7', 'Propósito del texto',
  '¿Cuál de las siguientes preguntas intenta responder el autor en este texto?',
  array['¿Por qué las revistas reconocidas perjudican el buen desarrollo de la ciencia?', '¿Por qué las investigaciones contemporáneas obstaculizan el avance de la ciencia?', '¿Cómo se obtienen los incentivos profesionales que ofrecen las revistas científicas?', '¿Qué tipo de artículos son los más apetecidos por el público de las revistas científicas?'],
  'Relaciona el título con la conclusión final.', 'publicada', 'modelo', 'e1740ddfb8aceb0e9916700e4203895f', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('99924e71-fdb1-4570-b943-0046d1f8c379', 0, 'El texto explica cómo las políticas y los incentivos de las revistas prestigiosas orientan la investigación hacia lo llamativo. La crítica se dirige a ese sistema, no a toda investigación contemporánea.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'fcbcc0a8-4739-4b43-8f03-2351d09197d5', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'proposito-del-texto'),
  (select id from public.lotes where codigo = '2026-B'),
  '4cf018c3-d106-4df6-a7ef-412983c439f7', 'Propósito del texto',
  'En este artículo, el autor se propone',
  array['denunciar los incentivos perjudiciales dirigidos a científicos y banqueros.', 'argumentar en contra de las políticas editoriales de las revistas científicas reconocidas.', 'presentarle al público general el sistema meritocrático que rige el mundo científico.', 'explicar por qué los mejores artículos científicos se publican en revistas reconocidas.'],
  'Identifica qué práctica quiere cambiar y qué razones ofrece.', 'publicada', 'modelo', 'f5ccad0ce39d37ba2d9376c80a319a55', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('fcbcc0a8-4739-4b43-8f03-2351d09197d5', 1, 'El autor da razones para cambiar las prácticas de las revistas de prestigio. La banca funciona como comparación; no es el segundo objeto principal del artículo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '686dc389-cb98-4456-b93d-d380448c58dc', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'semantica-y-lexico'),
  (select id from public.lotes where codigo = '2026-B'),
  'd02cd4ac-f22c-4f21-82e4-1c7c4c85390e', 'Semántica y léxico',
  'Cuando el narrador dice que una de las chicas francesas «asesina» el piano, quiere decir que',
  array['no sabe tocar aceptablemente el instrumento.', 'tergiversa las piezas musicales que interpreta.', 'estropea el instrumento por tocarlo violentamente.', 'adopta una actitud de desagrado frente al instrumento.'],
  'Interpreta la expresión según el tono crítico del narrador.', 'publicada', 'modelo', 'a61c22072b0687a2cd4bb65be26d37c0', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('686dc389-cb98-4456-b93d-d380448c58dc', 0, 'El verbo se usa figuradamente para expresar una interpretación musical muy mala. No informa un daño físico al piano.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '6a7b316e-9ac9-447f-a7a3-7d2fc4fefd7d', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  'd02cd4ac-f22c-4f21-82e4-1c7c4c85390e', 'Inferencia',
  'El narrador es',
  array['un muchachito de Brooklyn como aquel al que se refiere la cantante Janine.', 'un neoyorquino que considera ser alguien muy elegante y refinado.', 'un antiguo cliente de un bar ubicado en el elegante Hotel Seton.', 'un viajero que al pasar por Nueva York descubrió el Wicker Bar.'],
  'Busca una afirmación sobre su propia relación con el bar.', 'publicada', 'modelo', 'f1743ba78b3a6ccfc11874c02f5c5bc6', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('6a7b316e-9ac9-447f-a7a3-7d2fc4fefd7d', 2, 'Dice que antes le gustaba el lugar y que fue dejando de ir. Esa experiencia lo identifica como antiguo cliente, sin necesidad de atribuirle origen o profesión.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '033a0f42-883d-41d7-bca4-df22531008ba', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  'd02cd4ac-f22c-4f21-82e4-1c7c4c85390e', 'Inferencia',
  'El narrador se burla de Janine, porque',
  array['desprecia a los franceses.', 'él es una persona misógina.', 'la considera una artista mediocre.', 'la encuentra atractiva y ella lo ignora.'],
  'Apoya la causa en los juicios que expresa sobre la actuación.', 'publicada', 'modelo', '8d5db15883ede14d098465a45a3c405e', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('033a0f42-883d-41d7-bca4-df22531008ba', 2, 'Sus críticas se dirigen a la actuación, al modo de presentarse y a la canción que llama tontísima. El fragmento no sostiene las otras motivaciones.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '6ad41ad0-6637-4ca1-ae15-0b8e23d1ed93', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  'c6bd98d2-b599-4b6e-b462-0bb938059243', 'Inferencia',
  'Según el primer ministro, la situación es grave porque los resultados',
  array['tienen causas que no merecen investigarse.', 'tienen causas bien conocidas por todos.', 'cuestionan la legitimidad del jefe de Estado.', 'corroboran la tendencia observada días atrás.'],
  'Busca cómo compara la nueva votación con la anterior.', 'publicada', 'modelo', '8d22663852c868989412d62884dc6989', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('6ad41ad0-6637-4ca1-ae15-0b8e23d1ed93', 3, 'El ministro afirma que la votación confirma y agrava la tendencia del domingo anterior. A la vez niega expresamente que la legitimidad para seguir gobernando haya sido puesta en causa.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '4e8183e0-d6a2-42fa-acde-b148102be0af', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  'c6bd98d2-b599-4b6e-b462-0bb938059243', 'Inferencia',
  'De acuerdo con los resultados obtenidos, se puede afirmar que en la población hay un ambiente generalizado de',
  array['confianza en el Gobierno del momento.', 'abstencionismo, dado que no se valora la democracia.', 'inconformismo frente a todos los partidos políticos.', 'sorpresa, a raíz de los resultados de las elecciones anteriores.'],
  'Distingue no votar de participar y votar en blanco.', 'publicada', 'modelo', '249935238f42cd7e77fd8d0c285af61f', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4e8183e0-d6a2-42fa-acde-b148102be0af', 2, 'La gran mayoría participa pero vota en blanco, mientras los tres partidos reciben pocos votos. Eso apunta al rechazo de las opciones partidistas y no a abstención, que el texto fija en cero.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '90e84999-b221-4954-a990-90ebae83009f', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'informacion-literal'),
  (select id from public.lotes where codigo = '2026-B'),
  'c6bd98d2-b599-4b6e-b462-0bb938059243', 'Información literal',
  'En su discurso, el primer ministro se dirige a',
  array['el parlamento.', 'el jefe de Estado.', 'la población del país.', 'los habitantes de la ciudad.'],
  'Busca a quién convoca desde la tribuna pública.', 'publicada', 'modelo', '6f9cfb1e979031ab8d3523abdf37a75d', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('90e84999-b221-4954-a990-90ebae83009f', 3, 'El ministro dice explícitamente que convoca a los habitantes de la capital, a todos ellos. Parlamento y jefe de Estado aparecen como autoridades a las que solicitará medidas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '05c4ad5b-142b-4fae-ab9e-14831f86a570', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'semantica-y-lexico'),
  (select id from public.lotes where codigo = '2026-B'),
  'c6bd98d2-b599-4b6e-b462-0bb938059243', 'Semántica y léxico',
  'La expresión «bajo pena de» que aparece en el fragmento «bajo pena de convertirse en blanco directo de las sanciones previstas», al final del texto, puede reemplazarse por',
  array['«pagando la condena de».', '«pues corren el riesgo de».', '«con el dolor de tener que».', '«avergonzados por tener que».'],
  'Conserva el sentido de advertencia sobre una consecuencia.', 'publicada', 'modelo', '304d00db7730fb45be00ab370debf872', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('05c4ad5b-142b-4fae-ab9e-14831f86a570', 1, 'La expresión advierte una consecuencia punitiva posible si no se sigue lo exigido. No describe una condena ya pagada ni un sentimiento de tristeza o vergüenza.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'b19e0ff7-6986-4f5d-bfa9-7868d9e06d87', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'funcion-de-expresiones'),
  (select id from public.lotes where codigo = '2026-B'),
  'c6bd98d2-b599-4b6e-b462-0bb938059243', 'Función de expresiones',
  'El uso de la palabra «Finalmente», en la primera frase del texto, sugiere que',
  array['con su presencia el primer ministro concluyó el orden del día.', 'a las diez dio terminada una reunión el primer ministro.', 'se produjo algo que se esperaba desde hacía ya bastante tiempo.', 'aquella aparición fue lo último que el primer ministro hizo aquel día.'],
  'Distingue el final de una espera del final de todas las actividades del día.', 'publicada', 'modelo', '9d99b6415ce57fde8dc8c55aeba2a5d9', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b19e0ff7-6986-4f5d-bfa9-7868d9e06d87', 2, '«Finalmente» presenta la aparición como el término de una espera. No informa qué hizo luego el ministro ni que hubiese acabado una reunión.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '48edecd7-9d7f-4ca5-b7fa-a353f08876d7', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'tesis-y-argumentos'),
  (select id from public.lotes where codigo = '2026-B'),
  '42c68b30-1c9b-41a1-9e85-17bd092b58fc', 'Tesis y argumentos',
  'Al reformular las preguntas de Menón, Sócrates interpreta la tesis de su interlocutor en los siguientes términos:',
  array['No se puede investigar lo que se sabe ni lo que no se sabe.', 'Solamente se puede investigar lo que no se sabe.', 'Solamente se puede investigar lo que se sabe.', 'Se investiga lo que se anhela saber.'],
  'Lee el inicio de la última intervención de Sócrates.', 'publicada', 'modelo', '104f711d64b52f8bf54a52c25095b261', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('48edecd7-9d7f-4ca5-b7fa-a353f08876d7', 0, 'Sócrates formula expresamente la dificultad: lo conocido no requiere investigación y lo desconocido no se puede identificar para investigarlo. Está reconstruyendo la objeción de Menón, no anunciando su propia renuncia a investigar.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'b1a7c4a9-27a9-41c9-9b53-eee7a59a112d', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'punto-de-vista'),
  (select id from public.lotes where codigo = '2026-B'),
  '42c68b30-1c9b-41a1-9e85-17bd092b58fc', 'Punto de vista del autor',
  'En el texto, Sócrates se muestra como alguien que',
  array['tiene un conocimiento experto sobre la virtud.', 'duda que pueda conocerse la virtud.', 'quiere indagar acerca de la virtud.', 'muestra indiferencia por la virtud.'],
  'Relaciona la admisión de ignorancia con su decisión de investigar.', 'publicada', 'modelo', '81de8dccb97e6ea2072cf3c81b23b05d', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b1a7c4a9-27a9-41c9-9b53-eee7a59a112d', 2, 'Aunque admite no saber qué es la virtud, afirma estar decidido a considerarla e investigarla con Menón. Esa disposición es explícita.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'ad4372f6-3772-4633-900c-022a1fb75c00', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'textos-discontinuos'),
  (select id from public.lotes where codigo = '2026-B'),
  '9f600efd-eb88-4146-a5d9-d1200b1e4799', 'Textos discontinuos',
  '¿De qué manera acompañan los símbolos gráficos la información?',
  array['enfatizando visualmente los controles contra la corrupción.', 'ilustrando los actores políticos involucrados en las medidas.', 'destacando con dibujos aleatorios las medidas importantes.', 'agregando un elemento visual relacionado con el tema.'],
  'Relaciona cada símbolo con la medida que lo acompaña.', 'publicada', 'modelo', '0ad0a4674c61267c96f624c60864c26e', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('ad4372f6-3772-4633-900c-022a1fb75c00', 0, 'Los dibujos representan aspectos concretos de las medidas: vigilancia del dinero, prisión, cuentas y fundaciones. Enfatizan visualmente los controles descritos. La referencia genérica a un elemento relacionado con el tema es menos precisa.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'fd1f9b48-099f-4722-95c1-0d6e5b96273d', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  '9f600efd-eb88-4146-a5d9-d1200b1e4799', 'Estructura y articulación del texto',
  'Los números tienen la función de',
  array['enumerar las propuestas para darle claridad a la información.', 'clasificar las medidas propuestas por orden de importancia.', 'definir el orden en el que van a desarrollarse las propuestas.', 'establecer la secuencia del pacto con todas las fuerzas políticas.'],
  'No atribuyas orden temporal o jerarquía si el gráfico no los indica.', 'publicada', 'modelo', '1bed0c84258b50c44414267313f905bf', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('fd1f9b48-099f-4722-95c1-0d6e5b96273d', 0, 'Los números distinguen seis medidas. El gráfico no establece prioridades ni fechas de ejecución que permitan interpretarlos como un cronograma.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '50e94328-4f09-4370-84a7-c91851c5f692', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'funcion-de-expresiones'),
  (select id from public.lotes where codigo = '2026-B'),
  'e1a296d6-a34c-437b-b012-8feac6fb91ed', 'Función de expresiones',
  'El autor emplea el término «superstición» al final del primer párrafo con la intención de sugerir que',
  array['la creencia de que hay que obedecer siempre a los padres es injustificada.', 'la idea de que los padres tienen mejor criterio que los hijos es injustificada.', 'los jóvenes deben honrar solamente las creencias injustificadas de los padres.', 'los jóvenes, a diferencia de los padres, tienen creencias injustificadas.'],
  'Identifica el antecedente de «semejante».', 'publicada', 'modelo', '42ec8ec39e1ff34b4cf6c928fc861884', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('50e94328-4f09-4370-84a7-c91851c5f692', 1, '«Semejante superstición» retoma la creencia inmediatamente anterior: que los padres tienen mejor criterio. El tono irónico cuestiona esa superioridad supuesta.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'badd82b9-11e7-49f8-bba8-5ee3483b12a0', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'punto-de-vista'),
  (select id from public.lotes where codigo = '2026-B'),
  'e1a296d6-a34c-437b-b012-8feac6fb91ed', 'Punto de vista del autor',
  'De acuerdo con el autor, la afirmación «la verdad es poderosa y prevalece» es',
  array['verdadera, pues es una pulida y sonora máxima impuesta por un incomparable maestro de la Antigüedad.', 'falsa, pues la historia ofrece numerosos ejemplos de que la mentira puede ser más duradera que la verdad.', 'verdadera, pues la historia de nuestra raza, para no hablar de las experiencias individuales, apoya esa tesis.', 'falsa, pues para defenderla se requieren muchos años de estudio tedioso, pensamiento, práctica y experiencia.'],
  'Contrasta la máxima con la última oración.', 'publicada', 'modelo', '5fc5ee49cecc79e19bcdbdbbfdd09256', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('badd82b9-11e7-49f8-bba8-5ee3483b12a0', 1, 'El cierre sostiene que una verdad puede eliminarse mientras una mentira bien contada perdura. Con esa comparación el autor contradice la máxima, a la que llama impostura.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '8dbdc523-6e70-4adb-9d04-8e68504074fd', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  '8223e962-069d-4091-8a37-5e25afecbb43', 'Estructura y articulación del texto',
  '¿Cuál es la estrategia retórica dominante en el texto anterior?',
  array['Exageración de atributos de la personalidad.', 'Personificación de un objeto inanimado.', 'Comparación entre grupos étnicos.', 'Descripción de la apariencia.'],
  'Identifica qué clase de detalles se acumula a lo largo del pasaje.', 'publicada', 'modelo', '4c999a3afbb2c27a3a9b3e25cd48c87b', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('8dbdc523-6e70-4adb-9d04-8e68504074fd', 3, 'Predominan los detalles físicos de Mauki: pelo, piel, dentadura, perforaciones y adornos. Aunque hay información sobre costumbres y lugar de origen, no organiza la mayor parte del fragmento.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'c8326f8a-c98e-44d0-a6d4-497424fbaa73', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  '8223e962-069d-4091-8a37-5e25afecbb43', 'Estructura y articulación del texto',
  'El texto anterior es',
  array['un cuento autobiográfico.', 'una parte de un relato de aventuras.', 'una novela epistolar.', 'un fragmento de una crónica de Indias.'],
  'Usa la forma del fragmento y su atribución.', 'publicada', 'modelo', 'd18efb686987f1d4a55667ea9e9be3d1', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c8326f8a-c98e-44d0-a6d4-497424fbaa73', 1, 'La presentación de un personaje y su entorno corresponde a un relato; la atribución lo sitúa en Relatos de mares del sur. No tiene forma de carta ni de autobiografía y su marco no es la conquista americana.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'b9dc3305-331c-496f-a5bc-7bcda494cdb1', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  'dfe1325d-2936-42f7-b3b1-29cce190c3a2', 'Inferencia',
  'El fragmento lo narra',
  array['un observador neutral.', 'Johny, el protagonista.', 'un narrador omnisciente.', 'alguien que conoce a Johny.'],
  'Fíjate en las expresiones en primera persona.', 'publicada', 'modelo', '80c8d30c481af9e179b0d289014c4b70', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b9dc3305-331c-496f-a5bc-7bcda494cdb1', 3, 'La voz cuenta experiencias compartidas: habla de lo que comían y de los lugares a los que Johny la llevaba. Es alguien que participa en su entorno.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '4641b07c-39c9-4947-8398-55581582d72c', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  'dfe1325d-2936-42f7-b3b1-29cce190c3a2', 'Inferencia',
  'El adjetivo que mejor describe a Johny es',
  array['vividor.', 'generoso.', 'trabajador.', 'mezquino.'],
  'Relaciona los lujos con la procedencia del dinero.', 'publicada', 'modelo', 'f0ddf944b2a36e45cad5369503165335', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4641b07c-39c9-4947-8398-55581582d72c', 0, 'El relato subraya que mantiene lujos a expensas de su mujer y de un subsidio sin control. «Vividor» recoge ese aprovechamiento para sostener su estilo de vida.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'ab6179cc-85a3-4f99-9c7f-7a5e3f9222d4', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'semantica-y-lexico'),
  (select id from public.lotes where codigo = '2026-B'),
  'dfe1325d-2936-42f7-b3b1-29cce190c3a2', 'Semántica y léxico',
  '¿Cuál de los siguientes adjetivos es contrario a la palabra famélico?',
  array['Magro.', 'Enjuto.', 'Relleno.', 'Esquelético.'],
  'Busca la opción que no pertenece al grupo de la delgadez.', 'publicada', 'modelo', 'c7a6199769722f46f91ccc3904ea6327', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('ab6179cc-85a3-4f99-9c7f-7a5e3f9222d4', 2, 'Famélico alude al hambre extrema y aquí a una figura muy flaca. Magro, enjuto y esquelético comparten la delgadez; relleno expresa la característica contraria.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '9d2ccc9b-15ec-403b-a986-316784a45879', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  'b66492f7-169c-4773-9766-7d7347c705f6', 'Inferencia',
  'Los loros se asientan en los acantilados, al lado del mar, con el fin de',
  array['anidar y huir de cazadores.', 'reproducirse y resguardarse.', 'buscar pareja y alimentarse.', 'huir de cazadores y alimentarse.'],
  'Relaciona la descripción de los nidos con el calendario reproductivo.', 'publicada', 'modelo', '8b85336c5fb2d86991186b03747fa688', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9d2ccc9b-15ec-403b-a986-316784a45879', 1, 'La infografía destaca los nidos excavados, la pareja que los ocupa y las etapas de incubación y cría. Esos datos vinculan el asentamiento con refugio y reproducción. No indica que el acantilado sea su fuente de alimento.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '7be21a11-54a7-4d75-bf61-642b415ff962', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'textos-discontinuos'),
  (select id from public.lotes where codigo = '2026-B'),
  'b66492f7-169c-4773-9766-7d7347c705f6', 'Textos discontinuos',
  'La infografía está diseñada de manera que',
  array['toda la información se transmita a través de metáforas.', 'todos los datos se representen gráficamente.', 'las ilustraciones representen aquello a lo que se refiere la información.', 'la información se presente gráficamente, para evitar la utilización de cifras.'],
  'Comprueba cómo se relacionan los dibujos con sus rótulos.', 'publicada', 'modelo', '2b3ef2d7365ca8fa8b3f3ac80327332b', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('7be21a11-54a7-4d75-bf61-642b415ff962', 2, 'Los dibujos de loros, nidos y pichones corresponden a los asuntos descritos. También hay texto y cifras, por lo que no todos los datos son gráficos ni se evita usar números.');

